-- Idempotent install for rootcause.root_causes
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS rootcause;

CREATE TABLE IF NOT EXISTS rootcause.root_causes (
    root_cause_id character varying(40) NOT NULL,
    issue_id character varying(30) NOT NULL,
    name character varying(500) NOT NULL,
    slug character varying(500) NOT NULL,
    description text,
    topics character varying[],
    vendors_applicable character varying[] NOT NULL,
    vendor_considerations jsonb,
    search_text jsonb,
    created_at timestamp without time zone DEFAULT now() NOT NULL,
    updated_at timestamp without time zone DEFAULT now() NOT NULL
);

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE rootcause.root_causes);
SELECT root_cause_id, issue_id, name, slug, description, topics, vendors_applicable, vendor_considerations, search_text, created_at, updated_at FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM rootcause.root_causes);
DROP TABLE _stg_load;


DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'rootcause' AND c.relname = 'root_causes'
          AND con.conname = 'root_causes_pkey') THEN
        ALTER TABLE ONLY rootcause.root_causes
    ADD CONSTRAINT root_causes_pkey PRIMARY KEY (root_cause_id);
    END IF;
END $do$;
